def run(fmt):
    out = subprocess.run(['/workspace/executable','-n','1','-f',fmt],capture_output=True,text=True).stdout
    # strip graph prefix
    lines = out.split('\n')
    res = []
    for l in lines:
        if not l: continue
        res.append(l[4:])
    return '\\n'.join(res)
for n in (2,3,4):
    for perm in itertools.permutations('PS+-', n):
        fmt = '|'.join(mods[m] for m in perm)
