    brs = []
    ncommits = None
    for line in open('/tmp/cases/'+f):
        line=line.rstrip('\n')
        mm = line_re.match(line)
        if mm:
            name, col, _, st, _, en, merged, _, s, _, t = mm.groups()
            brs.append(dict(name=name, col=int(col), start=None if st is None else int(st), end=None if en is None else int(en), merged=merged=='m', s=None if s is None else int(s), t=None if t is None else int(t), group=group(name, m)))
        else:
            g = re.search(r'\((\d+) commits\)', line)
            if g: ncommits = int(g.group(1))
    if ncommits is None: continue
    cases.append((f, m, ncommits, brs))
print(len(cases), "cases")

BIG = 10**9
def simulate(brs, ncommits, ngroups, params):
    sortE, occE, check, keyrule, lenrule = params
    def E(b, mode):
        if b['end'] is not None: return b['end']
        return {'start': b['start'], 'n-1': ncommits-1, 'n': ncommits, 'MAX': BIG}[mode]
    items = []
    for i,b in enumerate(brs):
        if b['start'] is None: continue
        if b['end'] is None and sortE == 'skip': continue
        s, t = b['s'], b['t']
        if keyrule == 'max_or_MAX':
            key = max(s,t) if (s is not None and t is not None) else BIG
        elif keyrule == 'max_none0':
            key = max(s or 0, t or 0)
        elif keyrule == 't_or_MAX':
            key = t if t is not None else BIG
        se = E(b, sortE)
        ln = se - b['start'] if lenrule=='end-start' else 0
        items.append((key, ln, b['start'], i))
