        found = None
        for ci, ranges in enumerate(occupied[g]):
            conflict = False
            for (s2, e2) in ranges:
                if check == 'incl':
                    c = start <= e2 and ce >= s2
                elif check == 'end_in':
                    c = ce >= s2 and ce <= e2
                elif check == 'start_in':
                    c = start >= s2 and start <= e2
                elif check == 'either_in':
                    c = (start >= s2 and start <= e2) or (ce >= s2 and ce <= e2)
                if c: conflict = True; break
            if not conflict: found = ci; break
        if found is None:
            occupied[g].append([]); found = len(occupied[g])-1
        occupied[g][found].append((start, ce))
        cols[i] = found
    # offsets
    offs = []
    acc = 0
    for g in range(ngroups):
        offs.append(acc); acc += len(occupied[g])
    result = {}
    for i, c in cols.items():
        result[i] = offs[brs[i]['group']] + c
    return result

best = []
for params in itertools.product(['start','n-1','n','MAX','skip'], ['start','n-1','n','MAX'], ['incl','end_in','start_in','either_in'], ['max_or_MAX','max_none0','t_or_MAX'], ['end-start']):
