//! Settings: branching models, colors and output options.

use regex::Regex;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

/// Branching model as stored in the TOML model files.
#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct BranchSettingsDef {
    pub persistence: Vec<String>,
    pub order: Vec<String>,
    pub terminal_colors: ColorsDef,
    pub svg_colors: ColorsDef,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct ColorsDef {
    pub matches: Vec<(String, Vec<String>)>,
    pub unknown: Vec<String>,
}

/// Compiled branching model.
pub struct BranchSettings {
    pub persistence: Vec<Regex>,
    pub order: Vec<Regex>,
    pub terminal_colors: Vec<(Regex, Vec<String>)>,
    pub terminal_colors_unknown: Vec<String>,
    pub svg_colors: Vec<(Regex, Vec<String>)>,
    pub svg_colors_unknown: Vec<String>,
}

impl BranchSettings {
    pub fn from(def: &BranchSettingsDef) -> Result<Self, String> {
        let compile = |p: &str| Regex::new(p).map_err(|e| e.to_string());
        let mut persistence = Vec::new();
        for p in &def.persistence {
            persistence.push(compile(p)?);
        }
        let mut order = Vec::new();
        for p in &def.order {
            order.push(compile(p)?);
        }
        let mut terminal_colors = Vec::new();
        for (p, c) in &def.terminal_colors.matches {
            terminal_colors.push((compile(p)?, c.clone()));
        }
        let mut svg_colors = Vec::new();
        for (p, c) in &def.svg_colors.matches {
            svg_colors.push((compile(p)?, c.clone()));
        }
        Ok(BranchSettings {
            persistence,
            order,
            terminal_colors,
            terminal_colors_unknown: def.terminal_colors.unknown.clone(),
            svg_colors,
            svg_colors_unknown: def.svg_colors.unknown.clone(),
        })
    }
}

