/// Directory of the branching model files (creates the defaults if missing).
pub fn get_models_dir() -> Result<PathBuf, String> {
    let config = dirs::config_dir().ok_or_else(|| "Unable to determine config directory.".to_string())?;
    Ok(config.join("git-graph").join("models"))
}

pub fn create_models(models_dir: &Path) -> Result<(), String> {
    if !models_dir.exists() {
        std::fs::create_dir_all(models_dir).map_err(|e| e.to_string())?;
        for (name, content) in [("git-flow", MODEL_GIT_FLOW), ("simple", MODEL_SIMPLE), ("none", MODEL_NONE)] {
            let file = models_dir.join(format!("{}.toml", name));
            std::fs::write(&file, content).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

/// Names of all available models (file stems of .toml files in the models dir, in directory order).
pub fn get_available_models(models_dir: &Path) -> Result<Vec<String>, String> {
    let mut models = Vec::new();
    let entries = std::fs::read_dir(models_dir).map_err(|e| e.to_string())?;
    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();
        if path.is_file() {
            if let Some(ext) = path.extension() {
                if ext == "toml" {
                    if let Some(stem) = path.file_stem() {
                        models.push(stem.to_string_lossy().to_string());
                    }
                }
            }
        }
    }
    Ok(models)
}

/// Reads a branching model by name.
pub fn get_model(models_dir: &Path, model: &str, available: &[String]) -> Result<BranchSettingsDef, String> {
    let file = models_dir.join(format!("{}.toml", model));
    if !file.exists() {
        return Err(format!(
            "ERROR: No branching model named '{}' found in {}\n       Available models are: {}",
            model,
            models_dir.display(),
            available.join(", ")
        ));
    }
    let content = std::fs::read_to_string(&file).map_err(|e| e.to_string())?;
    toml::from_str::<BranchSettingsDef>(&content).map_err(|e| e.to_string())
}

/// Repository-specific model setting stored in `.git/git-graph.toml`.
#[derive(Serialize, Deserialize, Debug)]
pub struct RepoSettings {
    pub model: String,
}

pub fn get_repo_model_name(repo: &git2::Repository) -> Result<Option<String>, String> {
    let file = repo.path().join("git-graph.toml");
    if !file.exists() {
        return Ok(None);
    }
    let content = std::fs::read_to_string(&file).map_err(|e| e.to_string())?;
    let settings: RepoSettings = toml::from_str(&content).map_err(|e| e.to_string())?;
    Ok(Some(settings.model))
}

pub fn set_repo_model_name(repo: &git2::Repository, model: &str) -> Result<(), String> {
    let file = repo.path().join("git-graph.toml");
    let content = format!("model = \"{}\"\n", model);
    std::fs::write(&file, content).map_err(|e| e.to_string())
}

/// Terminal color index for a color name.
pub fn to_terminal_color(color: &str) -> Result<u8, String> {
    let c = match color {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright_black" => 8,
        "bright_red" => 9,
        "bright_green" => 10,
        "bright_yellow" => 11,
        "bright_blue" => 12,
        "bright_magenta" => 13,
        "bright_cyan" => 14,
        "bright_white" => 15,
        _ => match color.parse::<u8>() {
            Ok(v) => v,
            Err(_) => return Err(format!("Color {} not found", color)),
        },
    };
    Ok(c)
}

