//! Commit formatting (presets and custom placeholder formats).

use crate::graph::{CommitInfo, GitGraph};
use crate::print::colors::{paint_opt, HASH_COLOR, HEAD_COLOR};
use git2::{Commit, Time};

#[derive(Clone, Debug, PartialEq)]
pub enum CommitFormat {
    OneLine,
    Short,
    Medium,
    Full,
    Format(String),
}

impl CommitFormat {
    pub fn from_str(s: &str) -> CommitFormat {
        match s {
            "oneline" | "o" => CommitFormat::OneLine,
            "short" | "s" => CommitFormat::Short,
            "medium" | "m" => CommitFormat::Medium,
            "full" | "f" => CommitFormat::Full,
            _ => CommitFormat::Format(s.to_string()),
        }
    }
}

const DAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/// Civil date from days since 1970-01-01.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

struct DateTime {
    year: i64,
    month: u32,
    day: u32,
    hour: u32,
    minute: u32,
    second: u32,
    weekday: usize,
    offset_minutes: i32,
}

fn to_datetime(time: &Time) -> DateTime {
    let offset = time.offset_minutes();
    let local = time.seconds() + offset as i64 * 60;
    let days = local.div_euclid(86400);
    let secs = local.rem_euclid(86400);
    let (year, month, day) = civil_from_days(days);
    // 1970-01-01 was a Thursday (4)
    let weekday = ((days % 7 + 7 + 4) % 7) as usize;
    DateTime {
        year,
        month,
        day,
        hour: (secs / 3600) as u32,
        minute: ((secs % 3600) / 60) as u32,
        second: (secs % 60) as u32,
        weekday,
        offset_minutes: offset,
    }
}

/// Git default date format, e.g. `Fri Jan  1 10:17:00 2021 +0000`.
pub fn format_date(time: &Time) -> String {
    let dt = to_datetime(time);
    let sign = if dt.offset_minutes < 0 { '-' } else { '+' };
    let off = dt.offset_minutes.abs();
    format!(
        "{} {} {:>2} {:02}:{:02}:{:02} {} {}{:02}{:02}",
        DAYS[dt.weekday],
        MONTHS[(dt.month - 1) as usize],
        dt.day,
        dt.hour,
        dt.minute,
        dt.second,
        dt.year,
        sign,
        off / 60,
        off % 60
    )
}

/// Short date `YYYY-MM-DD`.
pub fn format_date_short(time: &Time) -> String {
    let dt = to_datetime(time);
    format!("{:04}-{:02}-{:02}", dt.year, dt.month, dt.day)
}

/// Relative date, e.g. `3 days ago`.
pub fn format_date_relative(time: &Time) -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let secs = (now - time.seconds()).max(0);
    if secs < 60 {
        format!("{} seconds ago", secs)
    } else if secs < 3600 {
        format!("{} minutes ago", secs / 60)
    } else if secs < 86400 {
        format!("{} hours ago", secs / 3600)
    } else if secs < 604800 {
        format!("{} days ago", secs / 86400)
    } else if secs < 2419200 {
        format!("{} weeks ago", secs / 604800)
    } else if secs < 31104000 {
        format!("{} months ago", secs / 2592000)
    } else {
        format!("{} years ago", secs / 31536000)
    }
}

/// Short (7 character) hash.
pub fn short_hash(oid: &git2::Oid) -> String {
    let s = oid.to_string();
    s[..7.min(s.len())].to_string()
}

/// Everything after the second line-feed of the message (git-graph's notion of the body).
pub fn body(message: &str) -> &str {
    let mut parts = message.splitn(3, '\n');
    parts.next();
    parts.next();
    parts.next().unwrap_or("")
}

/// Formats the references (branches and tags) of a commit, e.g. ` (HEAD -> master, dev) [v1.0]`.
pub fn format_branches(graph: &GitGraph, info: &CommitInfo, commit: &Commit, colored: bool) -> String {
    let head = &graph.head;
    let is_head = head.oid == commit.id();
    let branch_color = info
        .branch_trace
        .map(|t| graph.all_branches[t].visual.term_color)
        .unwrap_or(7);

    let mut out = String::new();
    if !info.branches.is_empty() || is_head {
        out.push(' ');
        if !info.branches.is_empty() {
            out.push('(');
        }
        if is_head {
            out.push_str(&paint_opt("HEAD ->", HEAD_COLOR, colored));
            if !info.branches.is_empty() {
                out.push(' ');
            }
        }
        for (i, &idx) in info.branches.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            let branch = &graph.all_branches[idx];
            out.push_str(&paint_opt(&branch.name, branch.visual.term_color, colored));
        }
        if !info.branches.is_empty() {
            out.push(')');
        }
    }
    if !info.tags.is_empty() {
        out.push_str(" [");
        for (i, &idx) in info.tags.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            let tag = &graph.all_branches[idx];
            let name = tag.name.strip_prefix("tags/").unwrap_or(&tag.name);
            out.push_str(&paint_opt(name, branch_color, colored));
        }
        out.push(']');
    }
    out
}

/// Formats a commit into lines of text.
pub fn format_commit(
    format: &CommitFormat,
    graph: &GitGraph,
    info: &CommitInfo,
    commit: &Commit,
    colored: bool,
) -> Result<Vec<String>, String> {
    let branches = format_branches(graph, info, commit, colored);
    let hash_color = HASH_COLOR;
    match format {
        CommitFormat::OneLine => {
            let line = format!(
                "{}{} {}",
                paint_opt(&short_hash(&commit.id()), hash_color, colored),
                branches,
                commit.summary().unwrap_or("").to_string()
            );
            Ok(vec![line])
        }
        CommitFormat::Short | CommitFormat::Medium | CommitFormat::Full => {
            let mut lines = Vec::new();
            lines.push(format!(
                "commit {}{}",
                paint_opt(&commit.id().to_string(), hash_color, colored),
                branches
            ));
            if commit.parent_count() > 1 {
                let parents: Vec<String> = commit.parent_ids().map(|p| short_hash(&p)).collect();
                lines.push(format!("Merge: {}", parents.join(" ")));
            }
            let author = commit.author();
            lines.push(format!(
                "Author: {} <{}>",
                author.name().unwrap_or(""),
                author.email().unwrap_or("")
            ));
            if *format == CommitFormat::Full {
                let committer = commit.committer();
                lines.push(format!(
                    "Commit: {} <{}>",
                    committer.name().unwrap_or(""),
                    committer.email().unwrap_or("")
                ));
            }
            if *format != CommitFormat::Short {
                lines.push(format!("Date:   {}", format_date(&author.when())));
            }
            lines.push(String::new());
            if *format == CommitFormat::Short {
                lines.push(format!("    {}", commit.summary().unwrap_or("")));
            } else {
                let message = commit.message().unwrap_or("");
                let message = message.strip_suffix('\n').unwrap_or(message);
                for line in message.split('\n') {
                    if line.is_empty() {
                        lines.push(String::new());
                    } else {
                        lines.push(format!("    {}", line));
                    }
                }
            }
            lines.push(String::new());
            Ok(lines)
        }
        CommitFormat::Format(fmt) => {
            let text = format_custom(fmt, commit, &branches, colored);
            let lines: Vec<String> = text.split('\n').filter(|l| !l.is_empty()).map(|l| l.to_string()).collect();
            Ok(lines)
        }
    }
}

const PLACEHOLDERS: [&str; 19] = [
    "an", "ae", "ad", "as", "ar", "cn", "ce", "cd", "cs", "cr", "n", "H", "h", "P", "p", "d", "s", "b", "B",
];

/// Expands a custom format string.
///
/// For each placeholder, the modifier variants are searched in the order
/// plain, space, plus, minus with a forward-moving cursor, which reproduces
/// the quirks of the original implementation.
fn format_custom(fmt: &str, commit: &Commit, branches: &str, colored: bool) -> String {
    let value = |ph: &str| -> String {
        match ph {
            "n" => "\n".to_string(),
            "H" => paint_opt(&commit.id().to_string(), HASH_COLOR, colored),
            "h" => paint_opt(&short_hash(&commit.id()), HASH_COLOR, colored),
            "P" => commit.parent_ids().map(|p| p.to_string()).collect::<Vec<_>>().join(" "),
            "p" => commit.parent_ids().map(|p| short_hash(&p)).collect::<Vec<_>>().join(" "),
            "d" => branches.to_string(),
            "s" => commit.summary().unwrap_or("").to_string(),
            "b" => body(commit.message().unwrap_or("")).to_string(),
            "B" => commit.message().unwrap_or("").to_string(),
            "an" => commit.author().name().unwrap_or("").to_string(),
            "ae" => commit.author().email().unwrap_or("").to_string(),
            "ad" => format_date(&commit.author().when()),
            "as" => format_date_short(&commit.author().when()),
            "ar" => format_date_relative(&commit.author().when()),
            "cn" => commit.committer().name().unwrap_or("").to_string(),
            "ce" => commit.committer().email().unwrap_or("").to_string(),
            "cd" => format_date(&commit.committer().when()),
            "cs" => format_date_short(&commit.committer().when()),
            "cr" => format_date_relative(&commit.committer().when()),
            _ => String::new(),
        }
    };

    // (byte position, pattern length, modifier, placeholder)
    let mut replacements: Vec<(usize, usize, Option<char>, &str)> = Vec::new();
    for ph in PLACEHOLDERS.iter() {
        let mut cursor = 0;
        for modifier in [None, Some(' '), Some('+'), Some('-')] {
            let pattern = match modifier {
                None => format!("%{}", ph),
                Some(m) => format!("%{}{}", m, ph),
            };
            while let Some(pos) = fmt[cursor..].find(&pattern) {
                let abs = cursor + pos;
                replacements.push((abs, pattern.len(), modifier, ph));
                cursor = abs + pattern.len();
            }
        }
    }
    replacements.sort_by_key(|r| r.0);
    // drop overlapping replacements (keep the earliest)
    let mut filtered: Vec<(usize, usize, Option<char>, &str)> = Vec::new();
    let mut last_end = 0;
    for r in replacements {
        if r.0 >= last_end {
            last_end = r.0 + r.1;
            filtered.push(r);
        }
    }

    let mut out = String::new();
    let mut pos = 0;
    for (start, len, modifier, ph) in filtered {
        out.push_str(&fmt[pos..start]);
        let val = value(ph);
        match modifier {
            None => out.push_str(&val),
            Some(' ') => {
                if !val.is_empty() {
                    out.push(' ');
                    out.push_str(&val);
                }
            }
            Some('+') => {
                if !val.is_empty() {
                    out.push('\n');
                    out.push_str(&val);
                }
            }
            Some('-') => {
                if val.is_empty() {
                    while out.ends_with('\n') {
                        out.pop();
                    }
                } else {
                    out.push_str(&val);
                }
            }
            _ => {}
        }
        pos = start + len;
    }
    out.push_str(&fmt[pos..]);
    out
}
