//! Graph construction: commits, branches, branch traces and columns.

use crate::settings::{to_terminal_color, BranchOrder, Settings};
use git2::{BranchType, Commit, Oid, Repository, Sort};
use std::collections::{HashMap, HashSet};

pub struct HeadInfo {
    pub oid: Oid,
    pub name: String,
    pub is_branch: bool,
}

pub struct CommitInfo {
    pub oid: Oid,
    pub is_merge: bool,
    pub parents: [Option<Oid>; 2],
    pub children: Vec<Oid>,
    pub branches: Vec<usize>,
    pub tags: Vec<usize>,
    pub branch_trace: Option<usize>,
}

pub struct BranchVis {
    pub order_group: usize,
    pub source_order_group: Option<usize>,
    pub target_order_group: Option<usize>,
    pub term_color: u8,
    pub svg_color: String,
    pub column: Option<usize>,
}

pub struct BranchInfo {
    pub target: Oid,
    pub merge_target: Option<Oid>,
    pub name: String,
    pub persistence: usize,
    pub is_remote: bool,
    pub is_merged: bool,
    pub is_tag: bool,
    pub visual: BranchVis,
    pub range: (Option<usize>, Option<usize>),
}

pub struct GitGraph {
    pub repository: Repository,
    pub commits: Vec<CommitInfo>,
    pub indices: HashMap<Oid, usize>,
    pub all_branches: Vec<BranchInfo>,
    pub head: HeadInfo,
}

impl GitGraph {
    pub fn new(mut repository: Repository, settings: &Settings, max_count: Option<usize>) -> Result<GitGraph, String> {
        let head = get_head(&repository)?;

        let mut stashes: HashSet<Oid> = HashSet::new();
        repository
            .stash_foreach(|_, _, oid| {
                stashes.insert(*oid);
                true
            })
            .map_err(|e| e.message().to_string())?;

        let mut walk = repository.revwalk().map_err(|e| e.message().to_string())?;
        walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)
            .map_err(|e| e.message().to_string())?;

        {
            let refs = repository.references().map_err(|e| e.message().to_string())?;
            for reference in refs {
                let reference = reference.map_err(|e| e.message().to_string())?;
                if reference.is_remote() && !settings.include_remote {
                    continue;
                }
                if let Ok(commit) = reference.peel_to_commit() {
                    walk.push(commit.id()).map_err(|e| e.message().to_string())?;
                }
            }
        }

        let mut commits = Vec::new();
        let mut indices: HashMap<Oid, usize> = HashMap::new();
        let mut idx = 0;
        let limit = max_count.unwrap_or(usize::MAX);
        for oid in walk {
            if idx >= limit {
                break;
            }
            let oid = oid.map_err(|e| e.message().to_string())?;
            if stashes.contains(&oid) {
                continue;
            }
            let commit = repository.find_commit(oid).map_err(|e| e.message().to_string())?;
            commits.push(CommitInfo::new(&commit));
            indices.insert(oid, idx);
            idx += 1;
        }

        assign_children(&mut commits, &indices);

        let mut all_branches = assign_branches(&repository, &mut commits, &indices, settings)?;
        assign_sources_targets(&commits, &indices, &mut all_branches);

        let (shortest_first, forward) = match settings.branch_order {
            BranchOrder::ShortestFirst(fwd) => (true, fwd),
            BranchOrder::LongestFirst(fwd) => (false, fwd),
        };
        assign_branch_columns(&commits, &indices, &mut all_branches, &settings.branches, shortest_first, forward);

        // filter out commits that are not assigned to any branch
        let filtered: Vec<CommitInfo> = commits
            .into_iter()
            .filter(|c| c.branch_trace.is_some())
            .collect();
        let mut index_map = vec![0usize; 0];
        {
            // index_map maps old indices to new ones (count of kept commits before)
            let mut kept = 0;
            index_map.reserve(idx + 1);
            // rebuild by walking old order: we need the original kept flags, so recompute from indices
            let mut kept_flags = vec![false; idx];
            for c in &filtered {
                kept_flags[indices[&c.oid]] = true;
            }
            for flag in kept_flags.iter() {
                index_map.push(kept);
                if *flag {
                    kept += 1;
                }
            }
            index_map.push(kept);
        }
        let commits = filtered;
        let indices: HashMap<Oid, usize> = commits.iter().enumerate().map(|(i, c)| (c.oid, i)).collect();
        for branch in all_branches.iter_mut() {
            if let Some(s) = branch.range.0 {
                branch.range.0 = Some(index_map[s]);
            }
            if let Some(e) = branch.range.1 {
                branch.range.1 = Some(index_map[e]);
            }
        }

        Ok(GitGraph {
            repository,
            commits,
            indices,
            all_branches,
            head,
        })
    }

    pub fn commit(&self, oid: Oid) -> Result<Commit, String> {
        self.repository.find_commit(oid).map_err(|e| e.message().to_string())
    }
}

impl CommitInfo {
    fn new(commit: &Commit) -> Self {
        CommitInfo {
            oid: commit.id(),
            is_merge: commit.parent_count() > 1,
            parents: [commit.parent_id(0).ok(), commit.parent_id(1).ok()],
            children: Vec::new(),
            branches: Vec::new(),
            tags: Vec::new(),
            branch_trace: None,
        }
    }
}

fn get_head(repository: &Repository) -> Result<HeadInfo, String> {
    let head = repository.head().map_err(|e| e.message().to_string())?;
    let name = head.name().unwrap_or("HEAD").to_string();
    let oid = head.target().ok_or_else(|| "Unable to resolve HEAD".to_string())?;
    Ok(HeadInfo {
        oid,
        name: name.strip_prefix("refs/heads/").unwrap_or(&name).to_string(),
        is_branch: head.is_branch(),
    })
}

fn assign_children(commits: &mut [CommitInfo], indices: &HashMap<Oid, usize>) {
    for i in 0..commits.len() {
        let oid = commits[i].oid;
        let parents = commits[i].parents;
        for parent in parents.iter().flatten() {
            if let Some(&p) = indices.get(parent) {
                commits[p].children.push(oid);
            }
        }
    }
}

fn match_index(patterns: &[regex::Regex], name: &str) -> usize {
    patterns
        .iter()
        .position(|p| p.is_match(name))
        .unwrap_or(patterns.len())
}

fn branch_color<T: Clone>(
    name: &str,
    matches: &[(regex::Regex, Vec<T>)],
    unknown: &[T],
    counter: usize,
) -> T {
    for (regex, colors) in matches {
        if regex.is_match(name) {
            return colors[counter % colors.len()].clone();
        }
    }
    unknown[counter % unknown.len()].clone()
}

fn new_branch(
    all_branches: &mut Vec<BranchInfo>,
    settings: &Settings,
    target: Oid,
    merge_target: Option<Oid>,
    name: String,
    is_remote: bool,
    is_merged: bool,
    is_tag: bool,
) -> Result<usize, String> {
    let match_name: String = if is_remote {
        name.splitn(2, '/').nth(1).unwrap_or(&name).to_string()
    } else {
        name.clone()
    };
    let counter = all_branches.len() + 1;
    let term_color_name = branch_color(
        &match_name,
        &settings.branches.terminal_colors,
        &settings.branches.terminal_colors_unknown,
        counter,
    );
    let term_color = to_terminal_color(&term_color_name)?;
    let svg_color = branch_color(
        &match_name,
        &settings.branches.svg_colors,
        &settings.branches.svg_colors_unknown,
        counter,
    );
    let persistence = match_index(&settings.branches.persistence, &match_name);
    let order_group = match_index(&settings.branches.order, &match_name);
    all_branches.push(BranchInfo {
        target,
        merge_target,
        name,
        persistence,
        is_remote,
        is_merged,
        is_tag,
        visual: BranchVis {
            order_group,
            source_order_group: None,
            target_order_group: None,
            term_color,
            svg_color,
            column: None,
        },
        range: (None, None),
    });
    Ok(all_branches.len() - 1)
}

fn assign_branches(
    repository: &Repository,
    commits: &mut [CommitInfo],
    indices: &HashMap<Oid, usize>,
    settings: &Settings,
) -> Result<Vec<BranchInfo>, String> {
    let mut all_branches: Vec<BranchInfo> = Vec::new();
    // (branch index, commit index, is_tag)
    let mut attachments: Vec<(usize, usize, bool)> = Vec::new();

    // local and remote branches
    let branches = repository.branches(None).map_err(|e| e.message().to_string())?;
    for branch in branches {
        let (branch, branch_type) = branch.map_err(|e| e.message().to_string())?;
        let is_remote = branch_type == BranchType::Remote;
        if is_remote && !settings.include_remote {
            continue;
        }
        let target = match branch.get().target() {
            Some(t) => t,
            None => continue,
        };
        let commit_idx = match indices.get(&target) {
            Some(&i) => i,
            None => continue,
        };
        let name = match branch.name().map_err(|e| e.message().to_string())? {
            Some(n) => n.to_string(),
            None => continue,
        };
        let bi = new_branch(&mut all_branches, settings, target, None, name, is_remote, false, false)?;
        attachments.push((bi, commit_idx, false));
    }

    // branches derived from merge commits
    for idx in 0..commits.len() {
        if !commits[idx].is_merge {
            continue;
        }
        let oid = commits[idx].oid;
        let commit = repository.find_commit(oid).map_err(|e| e.message().to_string())?;
        let summary = commit.summary().unwrap_or("");
        let name = parse_merge_summary(summary, &settings.merge_patterns);
        let second = commits[idx].parents[1].unwrap_or(oid);
        let bi = new_branch(&mut all_branches, settings, second, Some(oid), name, false, true, false)?;
        all_branches[bi].range.0 = Some(idx + 1);
    }

    // tags
    let tag_names = repository.tag_names(None).map_err(|e| e.message().to_string())?;
    for i in 0..tag_names.len() {
        let tag_name = match tag_names.get(i) {
            Some(Some(n)) => n.to_string(),
            _ => continue,
        };
        let reference = match repository.find_reference(&format!("refs/tags/{}", tag_name)) {
            Ok(r) => r,
            Err(_) => continue,
        };
        let target = match reference.peel_to_commit() {
            Ok(c) => c.id(),
            Err(_) => continue,
        };
        let commit_idx = match indices.get(&target) {
            Some(&i) => i,
            None => continue,
        };
        let bi = new_branch(
            &mut all_branches,
            settings,
            target,
            None,
            format!("tags/{}", tag_name),
            false,
            false,
            true,
        )?;
        attachments.push((bi, commit_idx, true));
    }

    // sort by persistence (stable), merged branches first within equal persistence
    let mut order: Vec<usize> = (0..all_branches.len()).collect();
    order.sort_by_key(|&i| (all_branches[i].persistence, !all_branches[i].is_merged));
    let mut new_index = vec![0usize; all_branches.len()];
    for (new, &old) in order.iter().enumerate() {
        new_index[old] = new;
    }
    let mut sorted: Vec<Option<BranchInfo>> = all_branches.into_iter().map(Some).collect();
    let mut all_branches: Vec<BranchInfo> = Vec::with_capacity(sorted.len());
    for &old in &order {
        all_branches.push(sorted[old].take().unwrap());
    }
    for (bi, commit_idx, is_tag) in attachments {
        let bi = new_index[bi];
        if is_tag {
            commits[commit_idx].tags.push(bi);
        } else {
            commits[commit_idx].branches.push(bi);
        }
    }

    // trace branches
    for bi in 0..all_branches.len() {
        trace_branch(commits, indices, &mut all_branches, bi);
    }

    // remove merged branches that do not own their start commit
    let mut keep = vec![true; all_branches.len()];
    for (bi, branch) in all_branches.iter().enumerate() {
        if branch.is_merged {
            let owns = indices
                .get(&branch.target)
                .map(|&i| commits[i].branch_trace == Some(bi))
                .unwrap_or(false);
            if !owns {
                keep[bi] = false;
            }
        }
    }
    if keep.iter().any(|k| !*k) {
        let mut remap = vec![None; all_branches.len()];
        let mut next = 0;
        for (i, k) in keep.iter().enumerate() {
            if *k {
                remap[i] = Some(next);
                next += 1;
            }
        }
        let mut kept: Vec<BranchInfo> = Vec::new();
        for (i, b) in all_branches.into_iter().enumerate() {
            if keep[i] {
                kept.push(b);
            }
        }
        all_branches = kept;
        for commit in commits.iter_mut() {
            commit.branch_trace = commit.branch_trace.and_then(|t| remap[t]);
            commit.branches = commit.branches.iter().filter_map(|&b| remap[b]).collect();
            commit.tags = commit.tags.iter().filter_map(|&b| remap[b]).collect();
        }
    }

    Ok(all_branches)
}

pub fn parse_merge_summary(summary: &str, patterns: &crate::settings::MergePatterns) -> String {
    for regex in &patterns.patterns {
        if let Some(caps) = regex.captures(summary) {
            if let Some(m) = caps.get(1) {
                return m.as_str().to_string();
            }
        }
    }
    "unknown".to_string()
}

/// Walks backwards along first parents, assigning commits to a branch.
fn trace_branch(commits: &mut [CommitInfo], indices: &HashMap<Oid, usize>, branches: &mut [BranchInfo], bi: usize) {
    let mut curr = branches[bi].target;
    let mut prev: Option<usize> = None;
    let mut end: Option<usize> = None;
    let mut any_assigned = false;

    while let Some(&idx) = indices.get(&curr) {
        if let Some(old) = commits[idx].branch_trace {
            if old == bi {
                break;
            }
            let same_name = branches[old].name == branches[bi].name;
            let old_start = branches[old].range.0.unwrap_or(0);
            let new_start = branches[bi].range.0.unwrap_or(idx);
            if same_name && old_start >= new_start {
                // the new branch takes over the commits of the old one
                match branches[old].range.1 {
                    Some(old_end) if idx > old_end => branches[old].range = (None, None),
                    _ => branches[old].range.0 = Some(idx),
                }
            } else {
                if same_name && branches[bi].is_merged && prev.is_some() && curr != branches[old].target {
                    branches[bi].name = format!("fork/{}", branches[bi].name);
                }
                if let Some(p) = prev {
                    if commits[p].is_merge {
                        let max_child = commits[idx]
                            .children
                            .iter()
                            .filter_map(|c| indices.get(c))
                            .max()
                            .copied()
                            .unwrap_or(idx.saturating_sub(1));
                        end = Some(max_child);
                    } else {
                        end = Some(idx.saturating_sub(1));
                    }
                }
                break;
            }
        }
        commits[idx].branch_trace = Some(bi);
        if branches[bi].range.0.is_none() {
            branches[bi].range.0 = Some(idx);
        }
        any_assigned = true;
        match commits[idx].parents[0] {
            None => {
                end = Some(idx);
                break;
            }
            Some(parent) => {
                prev = Some(idx);
                curr = parent;
            }
        }
    }

    if any_assigned {
        branches[bi].range.1 = end;
    } else if !branches[bi].is_merged {
        branches[bi].range = (None, None);
    }
}

fn assign_sources_targets(commits: &[CommitInfo], indices: &HashMap<Oid, usize>, branches: &mut [BranchInfo]) {
    for bi in 0..branches.len() {
        let target_group = branches[bi]
            .merge_target
            .and_then(|oid| indices.get(&oid))
            .and_then(|&idx| commits[idx].branch_trace)
            .map(|t| branches[t].visual.order_group);
        branches[bi].visual.target_order_group = target_group;
    }
    for info in commits {
        if let Some(trace) = info.branch_trace {
            let mut max_group: Option<usize> = None;
            for parent in info.parents.iter().flatten() {
                if let Some(&pidx) = indices.get(parent) {
                    if let Some(ptrace) = commits[pidx].branch_trace {
                        if ptrace != trace {
                            let group = branches[ptrace].visual.order_group;
                            if max_group.map_or(true, |g| group > g) {
                                max_group = Some(group);
                            }
                        }
                    }
                }
            }
            if let Some(g) = max_group {
                branches[trace].visual.source_order_group = Some(g);
            }
        }
    }
}

fn assign_branch_columns(
    _commits: &[CommitInfo],
    _indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    settings: &crate::settings::BranchSettings,
    shortest_first: bool,
    forward: bool,
) {
    let num_groups = settings.order.len() + 1;
    let mut occupied: Vec<Vec<Vec<(i64, i64)>>> = vec![Vec::new(); num_groups];
    let fallback_end = branches.len() as i64 - 1;

    // (index, start, end, group key)
    let mut branches_sort: Vec<(usize, i64, i64, i64)> = branches
        .iter()
        .enumerate()
        .filter_map(|(idx, br)| {
            br.range.0.map(|start| {
                let end = br.range.1.map(|e| e as i64).unwrap_or(fallback_end);
                let key = match (br.visual.source_order_group, br.visual.target_order_group) {
                    (Some(s), Some(t)) => s.max(t) as i64,
                    _ => i64::MAX,
                };
                (idx, start as i64, end, key)
            })
        })
        .collect();

    branches_sort.sort_by_key(|(_, start, end, key)| {
        let len = end - start;
        (
            *key,
            if shortest_first { len } else { -len },
            if forward { *start } else { -*start },
        )
    });

    for (idx, start, end, _) in branches_sort {
        let group = branches[idx].visual.order_group;
        let group_occ = &mut occupied[group];
        let mut found = None;
        for (col, ranges) in group_occ.iter().enumerate() {
            let conflict = ranges.iter().any(|&(s, e)| start <= e && end >= s);
            if !conflict {
                found = Some(col);
                break;
            }
        }
        let col = match found {
            Some(c) => c,
            None => {
                group_occ.push(Vec::new());
                group_occ.len() - 1
            }
        };
        group_occ[col].push((start, end));
        branches[idx].visual.column = Some(col);
    }

    let mut offsets = vec![0usize; num_groups];
    let mut acc = 0;
    for g in 0..num_groups {
        offsets[g] = acc;
        acc += occupied[g].len();
    }
    for branch in branches.iter_mut() {
        if let Some(col) = branch.visual.column {
            branch.visual.column = Some(col + offsets[branch.visual.order_group]);
        }
    }
}
