            end_flat[bi] = Some(e);
            let color = color_of_branch(bi);
            let last = e.min(total_rows);
            for r in (s + 1)..last {
                let cell = &mut flat[r].cells[col * 2 + 1];
                cell.0 = match cell.0 {
                    Cell::Hor => Cell::Cross,
                    Cell::Space => Cell::Ver,
                    other => other,
                };
                if cell.0 == Cell::Ver {
                    cell.1 = color;
                }
            }
        }
    }

