        if let (Some(col), Some(trace)) = (column_of(i), graph.commits[i].branch_trace) {
            let r = row_index[i][0];
            let cell = if graph.commits[i].is_merge { Cell::Circle } else { Cell::Dot };
            flat[r].cells[col * 2 + 1] = (cell, color_of_branch(trace));
        }
    }

    // horizontal lines
    for r in 0..total_rows {
        let lines = flat[r].lines.clone();
        for (from, to, color, kind) in lines {
            hline(&mut flat[r].cells, from, to, color as u8, kind);
        }
    }

