    let mut out_rows: Vec<(Vec<(Cell, u8)>, String)> = Vec::new();
    for i in 0..n {
        let info = &graph.commits[i];
        let commit = graph.commit(info.oid)?;
        let mut lines = format_commit(&settings.format, graph, info, &commit, settings.colored)?;
        if let Some((width_opt, indent1, indent2)) = &settings.wrapping {
            if let Some(w) = width_opt {
                let mut wrapped = Vec::new();
                for line in lines {
                    wrapped.extend(wrap_text(&line, *w, indent1.unwrap_or(0), indent2.unwrap_or(0)));
                }
                lines = wrapped;
            }
        }
        let ids = &row_index[i];
        let last_flat = *ids.last().unwrap();
        for (k, line) in lines.into_iter().enumerate() {
            if k < ids.len() {
                out_rows.push((flat[ids[k]].cells.clone(), line));
            } else {
                // extra row with the active vertical lines
                let mut cells = vec![(Cell::Space, 0); width];
                for bi in 0..nb {
                    if let (Some(s), Some(e), Some(col)) = (start_flat[bi], end_flat[bi], graph.all_branches[bi].visual.column) {
                        if s <= last_flat && e > last_flat {
                            cells[col * 2 + 1] = (Cell::Ver, color_of_branch(bi));
                        }
                    }
                }
                out_rows.push((cells, line));
            }
        }
        // remaining connector rows without text
        let used = out_rows.len();
        let _ = used;
        for k in 0..ids.len() {
            // rows beyond the number of text lines
            if k >= count_text_rows(&out_rows, i, k) {
                break;
            }
        }
    }
    unreachable!("replaced below");
}

fn count_text_rows(_o: &[(Vec<(Cell, u8)>, String)], _i: usize, _k: usize) -> usize {
    0
}

fn hline(cells: &mut [(Cell, u8)], from: usize, to: usize, color: u8, kind: LineKind) {
    let _ = (cells, from, to, color, kind);
}

#[allow(dead_code)]
fn unused(_f: &CommitFormat) {
    let _ = paint;
}
