//! Line wrapping (first-fit, hyphen splitting, ANSI-aware display width).

use unicode_width::UnicodeWidthChar;

fn ch_width(c: char) -> usize {
    UnicodeWidthChar::width(c).unwrap_or(0)
}

/// Display width of a string, skipping ANSI escape sequences.
pub fn display_width(text: &str) -> usize {
    let mut chars = text.chars();
    let mut width = 0;
    while let Some(ch) = chars.next() {
        if ch == '\x1b' {
            if let Some('[') = chars.clone().next() {
                chars.next();
                for c in chars.by_ref() {
                    if ('\x40'..='\x7e').contains(&c) {
                        break;
                    }
                }
                continue;
            }
        }
        width += ch_width(ch);
    }
    width
}

#[derive(Clone, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(s: &'a str) -> Word<'a> {
        let trimmed = s.trim_end_matches(' ');
        Word {
            word: trimmed,
            whitespace: &s[trimmed.len()..],
            penalty: "",
            width: display_width(trimmed),
        }
    }

    fn break_apart(&self, line_width: usize) -> Vec<Word<'a>> {
        let mut result = Vec::new();
        let mut offset = 0;
        let mut width = 0;
        for (idx, ch) in self.word.char_indices() {
            if width > 0 && width + ch_width(ch) > line_width {
                result.push(Word {
                    word: &self.word[offset..idx],
                    whitespace: "",
                    penalty: "",
                    width,
                });
                offset = idx;
                width = ch_width(ch);
            } else {
                width += ch_width(ch);
            }
        }
        if offset < self.word.len() {
            result.push(Word {
                word: &self.word[offset..],
                whitespace: self.whitespace,
                penalty: self.penalty,
                width,
            });
        }
        result
    }
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_whitespace = false;
    for (idx, ch) in line.char_indices() {
        if in_whitespace && ch != ' ' {
            words.push(Word::from(&line[start..idx]));
            start = idx;
        }
        in_whitespace = ch == ' ';
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn split_points(word: &str) -> Vec<usize> {
    let mut splits = Vec::new();
    for (idx, _) in word.match_indices('-') {
        let prev = word[..idx].chars().next_back();
        let next = word[idx + 1..].chars().next();
        if prev.filter(|c| c.is_alphanumeric()).is_some() && next.filter(|c| c.is_alphanumeric()).is_some() {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for word in words {
        let points = split_points(word.word);
        let mut prev = 0;
        for idx in points {
            let need_hyphen = !word.word[..idx].ends_with('-');
            result.push(Word {
                word: &word.word[prev..idx],
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
                width: display_width(&word.word[prev..idx]),
            });
            prev = idx;
        }
        if prev < word.word.len() || prev == 0 {
            result.push(Word {
                word: &word.word[prev..],
                whitespace: word.whitespace,
                penalty: word.penalty,
                width: display_width(&word.word[prev..]),
            });
        }
    }
    result
}

/// Wraps a single line (no line-feeds) into multiple lines.
pub fn wrap_text(line: &str, width: usize, indent1: usize, indent2: usize) -> Vec<String> {
    let initial_indent = " ".repeat(indent1);
    let subsequent_indent = " ".repeat(indent2);
    let mut lines: Vec<String> = Vec::new();

    if line.len() < width && initial_indent.is_empty() {
        lines.push(line.trim_end_matches(' ').to_string());
        return lines;
    }

    let initial_width = width.saturating_sub(indent1);
    let subsequent_width = width.saturating_sub(indent2);
    let line_widths = [initial_width, subsequent_width];

    let words = find_words(line);
    let split = split_words(words);
    let mut broken: Vec<Word> = Vec::new();
    for w in split {
        if w.width > line_widths[1] {
            broken.extend(w.break_apart(line_widths[1]));
        } else {
            broken.push(w);
        }
    }
    if !initial_indent.is_empty() {
        broken.insert(0, Word::from(""));
    }

    // first fit
    let mut wrapped: Vec<&[Word]> = Vec::new();
    let mut start = 0;
    let mut cur_width = 0usize;
    for (idx, frag) in broken.iter().enumerate() {
        let line_width = if wrapped.is_empty() { line_widths[0] } else { line_widths[1] };
        if cur_width + frag.width + frag.penalty.len() > line_width && idx > start {
            wrapped.push(&broken[start..idx]);
            start = idx;
            cur_width = 0;
        }
        cur_width += frag.width + frag.whitespace.len();
    }
    wrapped.push(&broken[start..]);

    let mut idx = 0;
    for words in wrapped {
        let last = match words.last() {
            None => {
                lines.push(String::new());
                continue;
            }
            Some(w) => w,
        };
        let len: usize = words.iter().map(|w| w.word.len() + w.whitespace.len()).sum::<usize>() - last.whitespace.len();
        let mut result = if lines.is_empty() {
            initial_indent.clone()
        } else {
            subsequent_indent.clone()
        };
        result.push_str(&line[idx..idx + len]);
        if !last.penalty.is_empty() {
            result.push_str(last.penalty);
        }
        lines.push(result);
        idx += len + last.whitespace.len();
    }
    lines
}
