//! SVG graph rendering.

use crate::graph::GitGraph;
use crate::settings::Settings;

fn fmt_num(v: f32) -> String {
    if v.fract() == 0.0 {
        format!("{}", v as i64)
    } else {
        format!("{}", v)
    }
}

pub fn print_svg(graph: &GitGraph, _settings: &Settings) -> Result<String, String> {
    let max_col = graph
        .all_branches
        .iter()
        .filter_map(|b| b.visual.column)
        .max()
        .unwrap_or(0);
    let num_cols = max_col + 1;
    let n = graph.commits.len();

    let mut elements: Vec<String> = Vec::new();

    let col_of = |idx: usize| -> Option<(usize, &str)> {
        graph.commits[idx]
            .branch_trace
            .and_then(|t| graph.all_branches[t].visual.column.map(|c| (c, graph.all_branches[t].visual.svg_color.as_str())))
    };

    for (idx, info) in graph.commits.iter().enumerate() {
        let (col, color) = match col_of(idx) {
            Some(c) => c,
            None => continue,
        };
        let x = (col as f32 + 1.0) * 15.0;
        let y = (idx as f32 + 1.0) * 15.0;
        for (p, parent) in info.parents.iter().enumerate() {
            let parent = match parent {
                Some(p) => p,
                None => continue,
            };
            let par_idx = match graph.indices.get(parent) {
                Some(&i) => i,
                None => continue,
            };
            let (par_col, par_color) = match col_of(par_idx) {
                Some(c) => c,
                None => continue,
            };
            let px = (par_col as f32 + 1.0) * 15.0;
            let py = (par_idx as f32 + 1.0) * 15.0;
            if par_col == col {
                elements.push(format!(
                    "<line stroke=\"{}\" stroke-width=\"1\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>",
                    color,
                    fmt_num(x),
                    fmt_num(px),
                    fmt_num(y),
                    fmt_num(py)
                ));
            } else {
                let (line_color, curve_y) = if p == 0 {
                    // fork: vertical first, curve at the end
                    (color, py - 15.0)
                } else {
                    // merge: curve first, vertical to the parent
                    (par_color, y)
                };
                let mid_y = curve_y + 7.5;
                let mid_x = (x + px) / 2.0;
                elements.push(format!(
                    "<path d=\"M{},{} L{},{} Q{},{},{},{} Q{},{},{},{} L{},{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
                    fmt_num(x),
                    fmt_num(y),
                    fmt_num(x),
                    fmt_num(curve_y),
                    fmt_num(x),
                    fmt_num(mid_y),
                    fmt_num(mid_x),
                    fmt_num(mid_y),
                    fmt_num(px),
                    fmt_num(mid_y),
                    fmt_num(px),
                    fmt_num(curve_y + 15.0),
                    fmt_num(px),
                    fmt_num(py),
                    line_color
                ));
            }
        }
        let fill = if info.is_merge { "white" } else { color };
        elements.push(format!(
            "<circle cx=\"{}\" cy=\"{}\" fill=\"{}\" r=\"4\" stroke=\"{}\" stroke-width=\"1\"/>",
            fmt_num(x),
            fmt_num(y),
            fill,
            color
        ));
    }

    let width = num_cols * 15;
    let height = (n + 2) * 15;
    let mut out = format!(
        "<svg height=\"{}\" viewBox=\"0 0 {} {}\" width=\"{}\" xmlns=\"http://www.w3.org/2000/svg\">\n",
        height, width, height, width
    );
    for e in elements {
        out.push_str(&e);
        out.push('\n');
    }
    out.push_str("</svg>");
    Ok(out)
}
