fn from_args() -> Result<(), String> {
    let matches = cli().get_matches();

    if matches.get_flag("skip-repo-owner-validation") {
        unsafe {
            let _ = git2::opts::set_verify_owner_validation(false);
        }
    }

    let path = matches.get_one::<String>("path").map(|s| s.as_str()).unwrap_or(".");

    let models_dir = get_models_dir()?;
    create_models(&models_dir)?;

    if let Some(sub) = matches.subcommand_matches("model") {
        if sub.get_flag("list") {
            let models = get_available_models(&models_dir)?;
            print!("{}", models.join("\n"));
            if !models.is_empty() {
                println!();
            }
            return Ok(());
        }
        let repository = open_repo(path)?;
        match sub.get_one::<String>("model") {
            Some(model) => {
                let available = get_available_models(&models_dir)?;
                get_model(&models_dir, model, &available)?;
                set_repo_model_name(&repository, model)?;
                print!("Branching model set to '{}'", model);
                let _ = std::io::stdout().flush();
            }
            None => {
                let model = get_repo_model_name(&repository)?;
                match model {
                    Some(m) => print!("{}", m),
                    None => print!("No branching model set"),
                }
                let _ = std::io::stdout().flush();
            }
        }
        return Ok(());
    }

    let repository = open_repo(path)?;

    let available = get_available_models(&models_dir)?;
    let model_name = match matches.get_one::<String>("model") {
        Some(m) => m.clone(),
        None => get_repo_model_name(&repository)?.unwrap_or_else(|| "git-flow".to_string()),
    };
    let model_def = get_model(&models_dir, &model_name, &available)?;
    let branches = BranchSettings::from(&model_def)?;

    let max_count = match matches.get_one::<String>("max-count") {
        Some(s) => match s.parse::<usize>() {
            Ok(v) => Some(v),
            Err(_) => return Err(format!("Option max-count must be a positive number, but got '{}'", s)),
        },
        None => None,
    };

    let no_color = matches.get_flag("no-color");
    let colored = if no_color {
        false
    } else {
        match matches.get_one::<String>("color").map(|s| s.as_str()) {
            Some("always") => true,
            Some("never") => false,
            Some("auto") | None => std::io::stdout().is_terminal(),
            Some(other) => {
                return Err(format!(
                    "Unknown color mode '{}'. Supports [auto|always|never].",
                    other
                ))
            }
        }
    };

    let style_name = matches.get_one::<String>("style").map(|s| s.as_str()).unwrap_or("thin");
    let characters = Characters::from_str(style_name)?;

    let format = match matches.get_one::<String>("format") {
        Some(f) => CommitFormat::from_str(f),
        None => CommitFormat::OneLine,
    };

    let wrapping = parse_wrapping(matches.get_many::<String>("wrap").map(|v| v.map(|s| s.as_str()).collect()))?;

    let settings = Settings {
        debug: matches.get_flag("debug"),
        colored,
        compact: !matches.get_flag("sparse"),
        include_remote: !matches.get_flag("local"),
        format,
        wrapping,
        characters,
        branch_order: BranchOrder::ShortestFirst(true),
        branches,
        merge_patterns: MergePatterns::default(),
        reverse: matches.get_flag("reverse"),
    };

    run(repository, &settings, matches.get_flag("svg"), max_count)
}

fn open_repo(path: &str) -> Result<Repository, String> {
    Repository::discover(path).map_err(|err| {
        format!(
            "ERROR: {}\n       Navigate into a repository before running git-graph, or use option --path",
            err.message()
        )
    })
}

fn parse_wrapping(args: Option<Vec<&str>>) -> Result<Option<(Option<usize>, Option<usize>, Option<usize>)>, String> {
    let args = match args {
        Some(a) => a,
        None => vec!["auto", "0", "8"],
    };
    if args.is_empty() {
        return Ok(None);
    }
    let width = match args[0] {
        "none" => return Ok(None),
        "auto" => {
            if std::io::stdout().is_terminal() {
                terminal_width()
            } else {
                return Ok(None);
            }
        }
        other => match other.parse::<usize>() {
            Ok(v) => Some(v),
            Err(_) => return Err(format!("ERROR: Can't parse option --wrap '{}' to integers.", args.join(" "))),
        },
    };
    let mut indents = [None, None];
    for (i, a) in args.iter().skip(1).take(2).enumerate() {
        match a.parse::<usize>() {
            Ok(v) => indents[i] = Some(v),
            Err(_) => return Err(format!("ERROR: Can't parse option --wrap '{}' to integers.", args.join(" "))),
        }
    }
    Ok(Some((width, indents[0], indents[1])))
}

fn terminal_width() -> Option<usize> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

fn run(repository: Repository, settings: &Settings, svg: bool, max_count: Option<usize>) -> Result<(), String> {
    let now = Instant::now();
    let graph = GitGraph::new(repository, settings, max_count)?;
    let duration_graph = now.elapsed().as_micros();

    if settings.debug {
        for branch in &graph.all_branches {
            eprintln!(
                "{} (col {}) ({:?}) {} s: {:?}, t: {:?}",
                branch.name,
                branch.visual.column.unwrap_or(99),
                branch.range,
                if branch.is_merged { "m" } else { "" },
                branch.visual.source_order_group,
                branch.visual.target_order_group
            );
        }
    }

    let now = Instant::now();
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    if svg {
        let s = print::svg::print_svg(&graph, settings)?;
        let _ = writeln!(out, "{}", s);
    } else {
        let lines = print::unicode::print_unicode(&graph, settings)?;
        for line in lines {
            let _ = writeln!(out, "{}", line);
        }
    }
    let _ = out.flush();
    let duration_print = now.elapsed().as_micros();

    if settings.debug {
        eprintln!(
            "Graph construction: {:.1} ms, printing: {:.1} ms ({} commits)",
            duration_graph as f32 / 1000.0,
            duration_print as f32 / 1000.0,
            graph.commits.len()
        );
    }
    let _ = REPO_CONFIG_FILE;
    Ok(())
}
