start = s.index("/// Paints a horizontal connection between two columns.")
new_tail = r'''/// Paints a vertical segment at `col` on the rows strictly between `from` and `to`.
fn vseg(flat: &mut [Row], segments: &mut Vec<(usize, usize, usize, u8)>, col: usize, from: usize, to: usize, color: u8) {
    segments.push((col, from, to, color));
    let last = to.min(flat.len());
    let x = col * 2 + 1;
    for r in (from + 1)..last {
        let cell = &mut flat[r].cells[x];
        match cell.0 {
            Cell::Space => *cell = (Cell::Ver, color),
            Cell::Hor => *cell = (Cell::Cross, color),
            Cell::Ver => cell.1 = color,
            Cell::RD => cell.0 = Cell::VerR,
            Cell::LD => cell.0 = Cell::VerL,
            Cell::RU => cell.0 = Cell::VerR,
            Cell::LU => cell.0 = Cell::VerL,
            Cell::HorU | Cell::HorD => cell.0 = Cell::Cross,
            _ => {}
        }
    }
}

/// Paints a horizontal connection between two columns.
fn hline(cells: &mut [(Cell, u8)], from: usize, to: usize, color: u8, kind: LineKind) {
    if from == to {
        return;
    }
    let (a, b) = (from.min(to), from.max(to));
    let xa = a * 2 + 1;
    let xb = b * 2 + 1;

    // cells strictly between the two columns
    for x in (xa + 1)..xb {
        let cell = &mut cells[x];
        match cell.0 {
            Cell::Space => *cell = (Cell::Hor, color),
            Cell::Ver => cell.0 = Cell::Cross,
            Cell::VerL | Cell::VerR => cell.0 = Cell::Cross,
            Cell::RD | Cell::LD | Cell::RU | Cell::LU => cell.0 = Cell::HorU,
            _ => {}
        }
    }

    match kind {
        LineKind::Fork => {
            // `from` is the ending branch, `to` is the target branch
            let (xf, xt) = (from * 2 + 1, to * 2 + 1);
            let left = to < from;
            let end_cell = &mut cells[xf];
            match end_cell.0 {
                Cell::Space => *end_cell = (if left { Cell::LU } else { Cell::RU }, color),
                Cell::Ver => end_cell.0 = if left { Cell::VerL } else { Cell::VerR },
                Cell::Hor => end_cell.0 = Cell::HorU,
                Cell::VerL | Cell::VerR | Cell::Cross | Cell::HorU | Cell::HorD => {}
                _ => *end_cell = (if left { Cell::LU } else { Cell::RU }, color),
            }
            let target = &mut cells[xt];
            match target.0 {
                Cell::Ver => target.0 = if left { Cell::VerR } else { Cell::VerL },
                Cell::VerR | Cell::VerL => target.0 = if left { Cell::VerR } else { Cell::VerL },
                Cell::Cross => {}
                Cell::Hor => target.0 = Cell::HorD,
                _ => *target = (if left { Cell::RD } else { Cell::LD }, color),
            }
        }
        LineKind::MergeCompact | LineKind::MergeBelow => {
            // `from` is the merge commit's column, `to` the merged branch
            let (xm, xs) = (from * 2 + 1, to * 2 + 1);
            let right = to > from;
            let arrow_x = if right { xm + 1 } else { xm - 1 };
            cells[arrow_x] = (if right { Cell::ArrL } else { Cell::ArrR }, color);
